<?php $__env->startSection('content'); ?><div class="mx-auto max-w-7xl space-y-5"><div><p class="text-sm font-bold uppercase tracking-widest text-indigo-600">Orders</p><h1 class="text-3xl font-black">Order Tracking</h1><p class="mt-1 text-sm text-slate-500">Track each order using its current status.</p></div><form class="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div class="flex gap-3"><input name="q" value="<?php echo e(request('q')); ?>" placeholder="Enter Order ID" class="min-w-0 flex-1 rounded-xl border border-slate-200 px-4 py-3"><button class="rounded-xl bg-slate-950 px-5 py-3 font-black text-white">Track</button></div></form><div class="grid gap-4"><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::openLoop(); ?><?php endif; ?><?php $__currentLoopData = $orders; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $o): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::startLoopIteration(); ?><?php endif; ?><div class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div><div class="text-lg font-black">Order #<?php echo e($o->order_id); ?></div><div class="mt-1 text-sm text-slate-500"><?php echo e($o->customer_name); ?> · <?php echo e($o->phone); ?></div></div><div class="text-right"><div class="text-lg font-black">৳ <?php echo e(number_format($o->total_amount,2)); ?></div><div class="text-xs font-bold text-slate-500"><?php echo e($o->created_at?->format('d M Y, h:i A')); ?></div></div></div><div class="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5"><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::openLoop(); ?><?php endif; ?><?php $__currentLoopData = ['Pending','Processing','Shipped','Completed','Cancelled']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $step): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::startLoopIteration(); ?><?php endif; ?><div class="text-center"><div class="mx-auto grid h-9 w-9 place-items-center rounded-full <?php echo e($o->order_status===$step?'bg-indigo-600 text-white':($step==='Cancelled'&&$o->order_status==='Cancelled'?'bg-red-600 text-white':'bg-slate-100 text-slate-400')); ?>"><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php if($step==='Pending'): ?><i class="fa-regular fa-clock text-xs"></i><?php elseif($step==='Processing'): ?><i class="fa-solid fa-gear text-xs"></i><?php elseif($step==='Shipped'): ?><i class="fa-solid fa-truck text-xs"></i><?php elseif($step==='Completed'): ?><i class="fa-solid fa-check text-xs"></i><?php else: ?><i class="fa-solid fa-xmark text-xs"></i><?php endif; ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?></div><div class="mt-2 text-[10px] font-bold text-slate-500"><?php echo e($step); ?></div></div><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::endLoop(); ?><?php endif; ?><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::closeLoop(); ?><?php endif; ?></div></div><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::endLoop(); ?><?php endif; ?><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::closeLoop(); ?><?php endif; ?></div><?php echo e($orders->links()); ?></div><?php $__env->stopSection(); ?>

